import mongoose from 'mongoose';

/**
 * Metadata for one file attached to a task. The file's bytes live in object storage; `storageKey` says where.
 * The key is generated by the server and is never sent to clients.
 */
const attachmentSchema = new mongoose.Schema(
  {
    task: { type: mongoose.Schema.Types.ObjectId, ref: 'Task', required: true, immutable: true },
    filename: { type: String, required: true, trim: true, maxlength: 255 },
    mimeType: { type: String, required: true }, // decided by the server from the file's content, not by the browser
    size: { type: Number, required: true, min: 1 },
    storageKey: { type: String, required: true, unique: true, select: false, immutable: true },
    uploadedBy: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true, immutable: true },
  },
  {
    timestamps: { createdAt: true, updatedAt: false },
    toJSON: {
      virtuals: true, // adds `id`
      transform(_doc, ret) {
        delete ret._id;
        delete ret.__v;
        delete ret.task; // the URL already names the task
        delete ret.storageKey;
        return ret;
      },
    },
  },
);

// "Attachments of one task, oldest first".
attachmentSchema.index({ task: 1, createdAt: 1 });

export const Attachment = mongoose.model('Attachment', attachmentSchema);
